const visual = {
  prepare: function (input) {
    return [
      { kind: 'text', payload: '0' },
      { kind: 'text', payload: '1' },
      { kind: 'text', payload: '1/3' },
      { kind: 'text', payload: '1/2' },
      { kind: 'text', payload: '1/3 < 1/2' }
    ];
  },
  render: function (input, metrics) {
    var W = (input && input.viewport && input.viewport.widthDu) || 640;
    var H = (input && input.viewport && input.viewport.heightDu) || 360;
    var fs = Math.max(11, Math.min(20, Math.round(Math.min(W, H) * 0.062)));
    var y = Math.round(H * 0.60);
    var padL = Math.round(W * 0.12);
    var padR = Math.round(W * 0.12);
    var x0 = padL;
    var x1 = W - padR;
    if (x1 - x0 < 140) { x0 = Math.round(W * 0.10); x1 = W - x0; }
    var unit = x1 - x0;
    var xThird = x0 + unit / 3;
    var xHalf = x0 + unit / 2;
    var over = Math.max(10, Math.round(W * 0.035));
    var tickH = Math.max(5, Math.round(H * 0.03));
    var r = Math.max(4, Math.round(W * 0.008));
    if (r > 7) { r = 7; }
    var head = Math.max(7, Math.round(fs * 0.5));
    var headV = Math.max(4, Math.round(fs * 0.28));

    var paths = [];
    paths.push({ id: 'line', commands: visualSdk.polyline([[x0 - over, y], [x1 + over, y]]) });
    paths.push({ id: 'tip', commands: visualSdk.polyline([[x1 + over - head, y - headV], [x1 + over, y], [x1 + over - head, y + headV]]) });
    paths.push({ id: 'tick0', commands: visualSdk.polyline([[x0, y - tickH], [x0, y + tickH]]) });
    paths.push({ id: 'tick1', commands: visualSdk.polyline([[x1, y - tickH], [x1, y + tickH]]) });
    paths.push({ id: 'dropA', commands: visualSdk.polyline([[xThird, y + r], [xThird, y + r + tickH]]) });
    paths.push({ id: 'dropB', commands: visualSdk.polyline([[xHalf, y + r], [xHalf, y + r + tickH]]) });
    paths.push({ id: 'dotA', commands: visualSdk.circle(xThird, y, r) });
    paths.push({ id: 'dotB', commands: visualSdk.circle(xHalf, y, r) });

    var labelY = y + r + tickH + fs + 4;
    var children = [
      { type: 'path', pathId: 'line', stroke: '#26354a', strokeWidth: 2, fill: 'none' },
      { type: 'path', pathId: 'tip', stroke: '#26354a', strokeWidth: 2, fill: 'none' },
      { type: 'path', pathId: 'tick0', stroke: '#26354a', strokeWidth: 2, fill: 'none' },
      { type: 'path', pathId: 'tick1', stroke: '#26354a', strokeWidth: 2, fill: 'none' },
      { type: 'path', pathId: 'dropA', stroke: '#26354a', strokeWidth: 1, fill: 'none' },
      { type: 'path', pathId: 'dropB', stroke: '#26354a', strokeWidth: 1, fill: 'none' },
      { type: 'path', pathId: 'dotA', stroke: '#b03a2e', strokeWidth: 2, fill: '#b03a2e' },
      { type: 'path', pathId: 'dotB', stroke: '#1f618d', strokeWidth: 2, fill: '#1f618d' },
      { type: 'label', text: '0', x: x0, y: labelY, fontSize: fs, anchor: 'middle', fill: '#26354a' },
      { type: 'label', text: '1', x: x1, y: labelY, fontSize: fs, anchor: 'middle', fill: '#26354a' },
      { type: 'label', text: '1/3', x: xThird, y: labelY, fontSize: fs, anchor: 'middle', fill: '#b03a2e' },
      { type: 'label', text: '1/2', x: xHalf, y: labelY, fontSize: fs, anchor: 'middle', fill: '#1f618d' },
      { type: 'label', text: '1/3 < 1/2', x: (xThird + xHalf) / 2, y: y - Math.round(fs * 1.4), fontSize: fs, anchor: 'middle', fill: '#26354a' }
    ];

    return {
      schemaVersion: 1,
      sceneId: 'numberline-fractions',
      revision: input.revision,
      viewBox: { x: 0, y: 0, width: W, height: H },
      paths: paths,
      root: { type: 'group', children: children }
    };
  }
};
